// spec: specs/businessdetail-gallery.md (2.1–2.4) · кейсы: .qa/tests/businessdetail-gallery/GALLERY-07..10.md · тикет #a6abaf (PR #201)
// seed: tests/seed.spec.ts (гость) · прод, только просмотр: SW выкл, не-GET блокируются, cookie «חיוניים בלבד», PWA «אולי מאוחר יותר».
// Устройства: @desktop (1440×900) и @iphone (iPhone 13 Mini, WebKit) — отдельными тестами, как в сценарии QA.
// Медленная сеть: ответы картинок supabase storage задерживаются на 1.2 с (page.route), выборка — каждый кадр rAF.
// Переход видео→картинка не проверяется — решение пользователя 2026-11-05: не баг.
import { test, expect } from '@playwright/test';
import {
  prepare, openListing, settledImage, readWindow, nextArrow, prevArrow, flip, LISTINGS, PX_TOL,
  delayStorageImages, holdStorageImages, startSampler, stopSampler, expectNoEmptyFrames, Shot, IMAGE_DELAY_MS,
} from './gallery.helpers';

test.use({ serviceWorkers: 'block' });

const DEVICES = ['@desktop', '@iphone'] as const;

/** Открыть «משתלה» с задержкой картинок и дождаться первой. Нет нескольких картинок — skip (данные прода). */
async function openMixed(page: import('@playwright/test').Page): Promise<Shot> {
  await delayStorageImages(page);
  await openListing(page, LISTINGS.mixed.id);
  const s = await settledImage(page, 'картинка 1');
  test.skip(!(await nextArrow(page).count()), 'в объявлении «משתלה» больше нет нескольких картинок — данные прода');
  return s;
}

/** То же, но соседи гарантированно не загружены: отпущена только первая картинка окна (holdStorageImages). */
async function openMixedHeld(page: import('@playwright/test').Page) {
  const hold = await holdStorageImages(page);
  await openListing(page, LISTINGS.mixed.id);
  await hold.allowWindowImage();
  const s1 = await settledImage(page, 'картинка 1');
  test.skip(!(await nextArrow(page).count()), 'в объявлении «משתלה» больше нет нескольких картинок — данные прода');
  return { s1, hold };
}

for (const dev of DEVICES) {
  test.describe(`Галерея: смена картинки без серого окна ${dev}`, () => {
    test.beforeEach(async ({ page }) => {
      await prepare(page);
    });

    test(`› и ‹ на медленной сети — ни одного кадра без картинки #a6abaf ${dev} @prod-safe`, async ({ page }) => {
      let s = await openMixed(page);
      const n = LISTINGS.mixed.count;
      await startSampler(page);
      const seen = [s.img!.src];
      for (let i = 2; i <= n; i++) {
        s = await flip(page, 'next', `› картинка ${i}`, s.img!.src);
        seen.push(s.img!.src);
      }
      for (let i = n - 1; i >= 1; i--) s = await flip(page, 'prev', `‹ картинка ${i}`, s.img!.src);
      const frames = await stopSampler(page);
      expect(new Set(seen).size, `пролистаны ${n} разных картинок`).toBe(n);
      expect(s.img!.src, '‹ вернула к картинке 1').toBe(seen[0]);
      expectNoEmptyFrames(frames, '› ×3 и ‹ ×3');
    });

    test(`› сразу после открытия (соседи не загружены) — старая картинка видна и окно не меняет размер, пока новая не загрузилась #a6abaf ${dev} @prod-safe`, async ({ page }) => {
      // Все картинки storage держатся; отпускается только первая картинка окна — соседи гарантированно не загружены.
      const { s1, hold } = await openMixedHeld(page);
      const old = s1.img!.src;
      await startSampler(page);
      await nextArrow(page).click();
      hold.releaseAll(); // картинка 2 ответит через 1.2 с после клика
      const s2 = await settledImage(page, '› картинка 2', old);
      const frames = await stopSampler(page);
      expectNoEmptyFrames(frames, '› сразу после открытия');

      // До кадра, где новая картинка загружена, — видна старая, размер окна прежний (±1 px).
      const firstNew = frames.findIndex((f) => f.loaded.some((src) => src !== old));
      expect(firstNew, 'новая картинка загрузилась во время выборки').toBeGreaterThan(0);
      const before = frames.slice(0, firstNew);
      const wrongCur = before.filter((f) => f.cur !== old);
      expect(wrongCur.length, `до загрузки новой видна старая картинка (кадров с другой: ${wrongCur.length} из ${before.length})`).toBe(0);
      const resized = before.filter((f) => Math.abs(f.w - s1.win.w) > PX_TOL || Math.abs(f.h - s1.win.h) > PX_TOL);
      expect(
        resized.length,
        `окно ${s1.win.w.toFixed(0)}×${s1.win.h.toFixed(0)} не меняется до загрузки новой (первый изменённый: ${resized[0] ? `${resized[0].w.toFixed(0)}×${resized[0].h.toFixed(0)} t=${resized[0].t}мс` : '—'})`,
      ).toBe(0);
      // Загрузка действительно шла с задержкой — иначе проверка «пока не загрузилась» пустая.
      expect(frames[firstNew].t, `новая картинка загрузилась не мгновенно (t=${frames[firstNew].t} мс)`).toBeGreaterThan(IMAGE_DELAY_MS * 0.8);
      expect(s2.img!.src).not.toBe(old);
    });

    test(`‹ сразу после открытия (соседи не загружены) — без кадров без картинки #a6abaf ${dev} @prod-safe`, async ({ page }) => {
      const { s1, hold } = await openMixedHeld(page);
      await startSampler(page);
      await prevArrow(page).click();
      hold.releaseAll();
      const s = await settledImage(page, '‹ с первой картинки', s1.img!.src);
      const frames = await stopSampler(page);
      expect(s.img!.src).not.toBe(s1.img!.src);
      expectNoEmptyFrames(frames, '‹ сразу после открытия');
    });

    test(`возврат к уже просмотренной картинке — без кадров без картинки #a6abaf ${dev} @prod-safe`, async ({ page }) => {
      let s = await openMixed(page);
      const first = s.img!.src;
      // Просмотреть все картинки (без выборки) — круг ›, затем вернуться ‹ к уже просмотренным.
      for (let i = 2; i <= LISTINGS.mixed.count; i++) s = await flip(page, 'next', `› картинка ${i}`, s.img!.src);
      await startSampler(page);
      for (let i = LISTINGS.mixed.count - 1; i >= 1; i--) s = await flip(page, 'prev', `‹ назад к картинке ${i}`, s.img!.src);
      s = await flip(page, 'next', '› снова картинка 2', s.img!.src);
      s = await flip(page, 'prev', '‹ снова картинка 1', s.img!.src);
      const frames = await stopSampler(page);
      expect(s.img!.src, 'вернулись к картинке 1').toBe(first);
      expectNoEmptyFrames(frames, 'возврат к просмотренным');
    });

    test(`листание › и ‹ не прокручивает страницу ни в одном кадре #a6abaf #154394 ${dev} @prod-safe`, async ({ page }) => {
      let s = await openMixed(page);
      // Небольшая прокрутка (галерея остаётся под стрелками, не под липкой шапкой): прыжок вверх тоже заметен.
      await page.evaluate(() => window.scrollTo(0, 100));
      await expect.poll(() => page.evaluate(() => window.scrollY), { message: 'страница прокручена на 100' }).toBe(100);
      await nextArrow(page).scrollIntoViewIfNeeded();
      await prevArrow(page).scrollIntoViewIfNeeded();
      const y0 = (await readWindow(page)).scrollY;
      await startSampler(page);
      s = await flip(page, 'next', '› картинка 2', s.img!.src);
      s = await flip(page, 'next', '› картинка 3', s.img!.src);
      s = await flip(page, 'prev', '‹ картинка 2', s.img!.src);
      const frames = await stopSampler(page);
      const moved = frames.filter((f) => Math.abs(f.sy - y0) > 1);
      expect(moved.length, `scrollY ${y0} не меняется ни в одном кадре (сдвинутых ${moved.length}, пример: ${moved[0]?.sy ?? '—'} t=${moved[0]?.t ?? '—'}мс)`).toBe(0);
      expect(Math.abs((await readWindow(page)).scrollY - y0), 'scrollY после листания').toBeLessThanOrEqual(1);
    });
  });
}
